describe('SavesCodecRegistry', () => {
  it('routes a bank source to the registered codec and reports it without host knowledge', async () => {
    const registry = new SavesCodecRegistry().register(codec)
    const route = await registry.route(bankSource('/tmp/endofdreamsbank2.SC2Bank'), {
      gameId: 'starcraft-2',
    })
    expect(route.status).toBe('resolved')
    if (route.status !== 'resolved') return
    expect(route.primary.detection.pluginId).toBe(SC2_BANK_CODEC_ID)

    const summaries = registry.summaries('starcraft-2')
    expect(summaries.map(summary => summary.id)).toEqual([SC2_BANK_CODEC_ID])
    expect(summaries[0]?.kind).toBe('save')
    expect(summaries[0]?.operationIds).toEqual(SC2_BANK_OPERATIONS.map(operation => operation.id))
  })

  it('does not route an unrecognized source', async () => {
    const registry = new SavesCodecRegistry().register(codec)
    const route = await registry.route(
      bankSource('/tmp/whatever.txt', new TextEncoder().encode('hello')),
    )
    expect(route.status).toBe('unrecognized')
    expect(
      await registry.open(bankSource('/tmp/whatever.txt', new TextEncoder().encode('hello'))),
    ).toBeUndefined()
  })

  it('rejects double registration', () => {
    const registry = new SavesCodecRegistry().register(codec)
    expect(() => registry.register(codec)).toThrow(/already registered/)
  })
})

